add('23797827e30526442a98','pnc-controller-owner-sized-drone-inventory-reader','ProgrammableController.loadAdditional','own inventory/tank, optional owner UUID/name, droneItems variable-size handler, energy, variables, chunk flags','restores owner/defaultfallback; temp handler defines usable drone slots; copies items then refreshes side configurator; retains variable compound','Controller owns two distinct inventories; destination drone slot capacity established before payload transfer.','UUID.fromString on malformed present ID throws; copy helper deep-copy behavior not resolved. Borrow size/owner initialization before restoring owned data, not arbitrary fallback identity for Dynasty player.')
add('0eee9835a4d183218e5f','pnc-programmer-item-and-edit-history-reader','Programmer.loadAdditional','Items inventory, programOnInsert flag, history list and programmable widget compounds','restores inventory, displayedStack derives from slot0; appends history and adds empty list if no history; loads program widgets','Persisted editor history not regenerated from current displayed item alone; no active program executed by this method.','history.addAll without clear may duplicate on repeated load. Borrow idempotent history/progress transfer; distinguish real receipts from current display cache.')
add('23120fc5174b5f5cbbdf','pnc-assembly-saved-program-continuation-reader','AssemblyController.loadAdditional','Items including PROGRAM_SLOT plus saved program fields, home flag/text','restores items first; only nonempty program item resolves curProgram; nonnull program then reads its saved continuation from root','Actual saved program identity chooses continuation decoder; prevents blindly loading one program data into an unknown/null program.','Does not explicitly clear stale curProgram when slot empty. Borrow source mechanism identity before interpreting old progress schema.')
add('882a10c7f155e0292f92','pnc-assembly-io-cargo-and-claw-state-reader','AssemblyIOUnit.loadAdditional','Items compound, clawProgress, clawClosing and state byte','restores carried inventory and associated physical operation state','Actual item owner restores both cargo and animation continuation; shows persistent on disk can include temporary motion state.','No state-byte range guard; no assertion claw state should persist across player death. Borrow permanent-versus-temporary classification by consumer semantics, not serialization alone.')
add('7c1e095a6054ce34f94b','pnc-pressure-interface-io-mode-reader','PressureChamberInterface.loadAdditional','Items, input/output progress, interfaceMode ordinal, exportAny','restores buffer/progress and direction mode via enum ordinal','Cargo restored into owned inventory rather than granted to player; operation mode controls interpretation of buffer.','Unchecked InterfaceDirection.values index can throw. Borrow checked schema/types when restoring old progression, not unchecked numeric enum assumption.')
add('dd1fc8e0c93dc9fce30c','pnc-pressure-chamber-fixed-capacity-payload-reader','PressureChamberValve.loadAdditional','multiblock geometry, variable-size itemsInChamber/craftedItems handlers, Valves int arrays','sets multiblock; copies inputs and outputs only up to each fixed max; clears/rebuilds valve position list only for arrays length3','Input and crafted output use independent capacity bounds; avoids slot exceptions while preserving supported-range payload.','Excess source slots silently omitted, not guaranteed lossless upgrade. Borrow validate capacity and report leftovers, never discard legacy player fields silently.')
add('7f341de6813d6b22f62f','pnc-air-cannon-cargo-and-tracked-item-reference-reader','AirCannon.loadAdditional','Items, target/GPS angles, force, tracked UUIDMost/Least records and optional previous inventory coordinates/side','restores cargo, rebuilds tracking set, reconstructs UUIDs from long pair; missing inventoryX clears both previous-position and side','Optional compound state clears paired fields together, preventing stale coordinate-side mismatch; tracking references kept with cargo.','Most/Least longs default0 if absent; no malformed entry checks. Borrow validate complete reference pair rather than broad prefix copy.')
add('53170bc49f86edecaa8e','pnc-smart-chest-slot-filter-reader','SmartChestItemHandler.deserializeNBT','super inventory payload plus LastSlot and Filter compound list with Slot index','base handler restores actual contents; reader restores cursor and parses filter stack at explicit slot','Saved items and filter policy are different roles; both must be considered when restoring container behavior.','filter[index] has no bounds check and array not cleared here; bad index throws and repeated import may keep stale filters. Borrow validated slot/key allowlist rather than copying arbitrary fields.')
add('6204e6a0d5c367878a98','ars-scribe-consumed-items-and-crafting-receipt-reader','ScribesTile.loadAdditional','itemStack, optional recipe ID, consumed item list, crafting ticks/status and autoYoink','restores output/input stack, recipe and consumed resources; crafting continuation restored; absent autoYoink defaults true','Restores consumed accounting alongside continuation rather than starting new craft/recharging resources. Local newly allocated itemsTag is unused, not credited as actual data transfer.','Recipe tryParse can yield null; consumed list helper failure behavior not studied. Borrow keep progress and spent-resource/claimed-reward receipts paired without executing reward.')
add('72a868163502ff9d98d8','ars-storage-lectern-inventory-links-reader','StorageLectern.loadAdditional','settings codec, invs position list, optional mainLecternPos and bookwyrm UUID array list','clears/rebuilds inventory links with null runtime handlers, resets main link, rebuilds bookwyrm UUID set and marks updateItems','Stores reference positions then rebuilds runtime item handlers later; copying live handler references would be wrong.','Invalid UUID array can throw; positions may point to absent blocks. Borrow detach runtime references from durable owner data and validate optional identity fields.')
add('f207d9aa960aa927cc3e','ars-wixie-in-progress-craft-and-bound-storage-reader','WixieCauldron.loadAdditional','currentCraft stack, CraftingManager tag, entity/mana/potion flags, craftingIndex, boundedInvs and cooldown','restores actual crafting stack and manager, reinitializes bounded storage position list, retains progress index and cooldown','Incomplete craft state spans payload+manager+resource availability, not one integer; list rebuilt instead of appended.','Nested manager decoder not independently credited. Cooldown serialization is not grounds for death retention; Dynasty needs semantic permanent whitelist.')
add('fa67bd88c54574b81344','ars-bookwyrm-held-item-and-home-reader','EntityBookwyrm.readAdditionalSaveData','optional lectern position, held item compound, backoff and optional color','restores held cargo and home link, backoff; color only when present','Cargo is actual saved stack independent of color customization. Real item-bearing entity reader qualifies; cosmetic color field does not receive separate credit.','Absent lectern does not clear old field; parseOptional can yield empty. Borrow missing-field policy per role rather than treat all fields as required.')
add('0e6e468950e53a327849','ars-flying-item-payload-flight-continuation-reader','EntityFlyingItem.load','item compound, age, offset flags/amount and from/to vectors','loads carried ItemStack into entityData, then restores flight continuation','Real item transfer entity owns cargo persisted with travel endpoints; restoring only trajectory would lose payload.','No validation visible for age/vector schema and entityData updates may sync later. Borrow preserve real payload and only audited metadata, no blanket client state copying.')
add('76ab488a8ac4edfc47d3','ars-starbuncle-behavior-cargo-restore','Starbuncle.readAdditionalSaveData','optional starbuncleData charm schema, held item, backoff and tamed flag','decodes mutable charm data/default compound; creates behavior; restores held cargo/tamed; initializes goals once and restores behavior tag; sync only server','Durable behavior definition is rebuilt into runtime strategy; guarded one-time goal reset avoids stacking duplicate goals.','Registry behavior may be null; nested charm codec defaults not all traced. Borrow explicit new-owner initialization and schema-bound field restore rather than copying old manager references.')
add('26b804cd5898f7142a0c','curios-slots-payload-and-modifier-lifetime-reader','CurioStacksHandler.deserialize ValueInput','base/slot sizes, stack/cosmetic children, render/active lists, role flags/drop rule, PermanentModifiers versus Modifiers','resizes first; restores stacks; restores toggles with current-value defaults; permanent modifiers through addPermanentModifier, other list through addTransientModifier','Same persistent record explicitly distinguishes permanent and transient modifier lifetimes. Both are serialized, so serialization alone cannot define death permanence.','Render/active loops unbounded to target size may throw; modifiers added without visible clear here. Borrow whitelist correct lifetime fields and avoid duplicating existing Dynasty slot/PlayerPersisted clone ownership.')
